const $=s=>document.querySelector(s);
async function request(path,options={}){const r=await fetch(path,{credentials:'same-origin',headers:{'content-type':'application/json',...(options.headers||{})},...options});const data=await r.json().catch(()=>({}));if(!r.ok)throw new Error(data.error||'Operación no disponible');return data}
function showSetup(){document.body.dataset.auth='setup';$('#loginView').hidden=false;$('#setupForm').hidden=false;$('#loginForm').hidden=true;$('#appShell').hidden=true;$('#setupEmail').focus()}
function showLogin(){document.body.dataset.auth='anonymous';$('#loginView').hidden=false;$('#setupForm').hidden=true;$('#loginForm').hidden=false;$('#appShell').hidden=true;$('#email').focus()}
function showApp(me){document.body.dataset.auth='authenticated';$('#loginView').hidden=true;$('#setupForm').hidden=true;$('#loginForm').hidden=true;$('#appShell').hidden=false;$('#sessionUser').textContent=me.email;$('#sessionRole').textContent=me.role;window.AUTH={...me,request:async(path,opt={})=>request(path,{...opt,headers:{...(opt.headers||{}),'x-csrf-token':me.csrf_token}})};window.dispatchEvent(new CustomEvent('auth:ready',{detail:me}))}
async function session(){try{const me=await request('/api/auth/me');showApp(me)}catch{showLogin()}}
async function initialize(){try{const status=await request('/api/auth/setup-status');if(status.needs_setup)return showSetup();await session()}catch(error){showLogin();$('#loginNotice').textContent='No fue posible comprobar la configuración inicial. '+error.message}}
$('#setupForm').addEventListener('submit',async e=>{e.preventDefault();const button=$('#setupSubmit'),notice=$('#setupNotice'),form=new FormData(e.currentTarget),email=String(form.get('email')||'').trim(),password=String(form.get('password')||''),confirmation=String(form.get('confirm_password')||'');if(password!==confirmation){notice.textContent='Las contraseñas no coinciden.';return}button.disabled=true;notice.textContent='Creando acceso seguro…';try{await request('/api/auth/bootstrap-admin',{method:'POST',body:JSON.stringify({email,password})});await request('/api/auth/login',{method:'POST',body:JSON.stringify({email,password})});e.currentTarget.reset();await session()}catch(error){notice.textContent=error.message}finally{button.disabled=false}});
$('#loginForm').addEventListener('submit',async e=>{e.preventDefault();const button=$('#loginSubmit'),notice=$('#loginNotice');button.disabled=true;notice.textContent='Verificando…';try{const form=new FormData(e.currentTarget);await request('/api/auth/login',{method:'POST',body:JSON.stringify({email:form.get('email'),password:form.get('password')})});e.currentTarget.reset();await session()}catch(error){notice.textContent=error.message}finally{button.disabled=false}});
$('#logout').addEventListener('click',async()=>{try{const me=window.AUTH;await request('/api/auth/logout',{method:'POST',headers:{'x-csrf-token':me?.csrf_token||''}})}finally{window.AUTH=null;showLogin()}});
initialize();
